void need(bool b,const char*m){++checks;if(!b)throw std::runtime_error(m);}
struct Reader{std::span<const std::uint8_t>b;std::size_t at{};auto take(std::size_t n){need(n<=b.size()-at,"fixture truncated");auto v=b.subspan(at,n);at+=n;return v;}U word(){auto v=take(4);return U(v[0])|(U(v[1])<<8)|(U(v[2])<<16)|(U(v[3])<<24);}std::string text(){auto n=word();need(n<=256,"text extent");auto b=take(n);return{b.begin(),b.end()};}void end(){need(at==b.size(),"fixture trailing");}};
constexpr std::array<U,11> addresses{0x2000000,0x2100000,0x2200000,0x2300000,0x2400000,0x2500000,0x2600000,0x2700000,0x2800000,0x2900000,0x2a00000};
constexpr std::array<U,11> sizes{0xb000,0xa000,0x1000,0x1000,0x1000,0xe000,0x1000,0xa000,0x5000,0x8000,0x1000};
constexpr std::array<const char*,11> names{"player","pbw","pw","global","object","context","pad","mode2_object","world_manager","world_records","world_context"};
U read(const Bytes&b,U o,U n=4){return cp::read(b,o,n);}void write(Bytes&b,U o,U n,U v){need(n<=4&&o<=b.size()&&n<=b.size()-o,"projection extent");for(U i=0;i<n;++i)b[o+i]=std::uint8_t(v>>(i*8));}
struct Setup{std::array<Bytes,11> arenas;std::vector<std::pair<U,U>> known;std::map<U,Bytes> globals;wl::Manager manager;px::Context context;cp::Input input;};
bool known(const Setup&x,U a,U n){for(U i=0;i<n;++i)if(!std::any_of(x.known.begin(),x.known.end(),[&](auto r){return r.first<=a+i&&a+i<r.second;}))return false;return true;}
template<class T>std::optional<T> field(const Setup&x,U arena,U off,U width){if(!known(x,addresses[arena]+off,width))return{};const U v=read(x.arenas[arena],off,width);if constexpr(std::is_same_v<T,std::int8_t>)return std::bit_cast<std::int8_t>(std::uint8_t(v));else return T(v);}
wl::Link link(U p,U count){if(p==0)return wl::Absent{};need(p>=addresses[9]&&p<addresses[9]+count*256&&((p-addresses[9])%256)==0,"record link identity");return wl::Index{(p-addresses[9])/256};}
A primary(const Setup&x){return{x.arenas[0],x.arenas[1],x.arenas[2]};}
void setup(Setup&x,U count){need(count<=128,"record capacity");for(U i=0;i<3;++i)need(known(x,addresses[i],sizes[i]),"canonical arena knowledge");need(known(x,addresses[3]+0x2b,1)&&known(x,addresses[3]+0x2f,1),"global canonical knowledge");need(known(x,addresses[8]+0x4a1c,4),"head knowledge");x.input=cp::decode(primary(x));auto&g=x.input.p.global;g.field22=std::uint16_t(read(x.arenas[3],0x22,2));g.field2b=*field<std::uint8_t>(x,3,0x2b,1);g.field2f=*field<std::uint8_t>(x,3,0x2f,1);g.field5d=std::uint8_t(read(x.arenas[3],0x5d,1));g.fieldd72=field<std::uint8_t>(x,3,0xd72,1);
 auto& c=x.context.filter;c.object20=field<std::int8_t>(x,4,0x20,1);c.object21=field<std::int8_t>(x,4,0x21,1);c.manager={field<std::uint8_t>(x,5,0xad24,1),field<U>(x,5,0xad50,4),field<U>(x,5,0xad64,4),field<std::int8_t>(x,5,0xad20,1)};
 const auto mode=read(x.globals.at(0xedbe90),0);need(mode==0||mode==addresses[7],"mode pointer identity");if(mode)c.mode2=fi::Mode2Object{field<std::uint8_t>(x,7,0x984c,1),field<std::uint8_t>(x,7,0x982f,1)};else c.mode2=fi::Absent{};
 c.byte108b9b8=std::uint8_t(read(x.globals.at(0x108b9b8),0,1));c.byte1083850=std::uint8_t(read(x.globals.at(0x1083850),0,1));c.byte109bd29=std::uint8_t(read(x.globals.at(0x109bd29),0,1));c.pad={field<std::uint16_t>(x,6,0x31e,2),field<std::uint16_t>(x,6,0x31c,2),field<std::uint16_t>(x,6,0x320,2),field<std::uint16_t>(x,6,0x32c,2),field<std::uint16_t>(x,6,0x32e,2),field<std::uint16_t>(x,6,0x338,2),field<std::uint16_t>(x,6,0x33a,2)};
 x.context.delta_bits=field<U>(x,0,0x14,4);x.manager.head=link(read(x.arenas[8],0x4a1c),count);
 for(U i=0;i<count;++i){auto&r=x.manager.records[i];const U o=i*256;auto following=field<U>(x,9,o+8,4);need(following.has_value(),"next knowledge");r.next=link(*following,count);
 #define REC(name,off,T,n) r.name=field<T>(x,9,o+off,n)
 REC(field19,0x19,std::uint8_t,1);REC(field2f,0x2f,std::uint8_t,1);REC(field54,0x54,std::uint8_t,1);REC(field61,0x61,std::uint8_t,1);REC(field78,0x78,std::uint8_t,1);REC(field30,0x30,std::uint16_t,2);REC(field4c_bits,0x4c,U,4);REC(field50_bits,0x50,U,4);REC(field28,0x28,U,4);
 #undef REC
 for(U j=0;j<3;++j){r.fields34[j]=field<U>(x,9,o+0x34+4*j,4);r.fields40[j]=field<U>(x,9,o+0x40+4*j,4);}}
 x.context.world={&x.manager,field<U>(x,10,0x14,4)};
 for(auto[ptr,expected]:std::array<std::pair<U,U>,6>{{{0xfb6b7c,addresses[3]},{0xfb5edc,addresses[4]},{0xfbeffc,addresses[5]},{0x10572d8,addresses[6]},{0xfb8a1c,addresses[8]},{0xfcf45c,addresses[10]}}})need(read(x.globals.at(ptr),0)==expected,"global pointer binding");need(read(x.arenas[0],0xe30)==addresses[1]&&read(x.arenas[0],0xa29c)==addresses[2],"player pointers");}
auto context_value(const px::Context& c){const auto&f=c.filter;std::optional<std::uint8_t>a,b;if(auto m=std::get_if<fi::Mode2Object>(&f.mode2)){a=m->field984c;b=m->field982f;}return std::tuple{c.delta_bits,c.world.area_mask14,f.object20,f.object21,f.mode2.index(),a,b,f.manager.ad24,f.manager.ad50,f.manager.ad64,f.manager.ad20,f.byte108b9b8,f.byte1083850,f.byte109bd29,f.pad.field31e,f.pad.field31c,f.pad.field320,f.pad.field32c,f.pad.field32e,f.pad.field338,f.pad.field33a};}
void expected(const cp::Input&out,const A&arena,const mh4u::player_transition::GlobalFields&g){auto e=cp::decode(arena);e.p.global=g;need(out.p==e.p,"canonical player checkpoint differs from ARM");need(out.f==e.f,"shared fields checkpoint differs from ARM");}
void project_block(A&a,const cp::Input&x){const auto&p=x.p;const auto&f=x.f;for(U i=0;i<2;++i){write(a[1],0x3c0+2*i,2,p.pbw.angles[i]);write(a[1],0x3c4+2*i,2,p.pbw.magnitudes[i]);}write(a[1],0x3d4,4,p.pbw.field3d4);write(a[1],0x451,1,p.pbw.field451);
 for(auto [o,v]:std::array<std::pair<U,std::optional<std::uint16_t>>,4>{{{0x3a8,f.pbw.field3a8},{0x3ac,f.pbw.field3ac},{0x3b8,f.pbw.field3b8},{0x3bc,f.pbw.field3bc}}}){need(v.has_value(),"unknown output halfword");write(a[1],o,2,*v);}for(U i=0;i<19;++i)for(U j=0;j<4;++j){need(f.pbw.words3d8[i][j].has_value(),"unknown word lane");write(a[1],0x3d8+4*i+j,1,*f.pbw.words3d8[i][j]);}
 for(U i=0;i<99;++i){need(f.pbw.input_other[i].has_value(),"unknown extra lane");write(a[1],mh4u::player_input_storage::remaining_offsets[i],1,*f.pbw.input_other[i]);}}
void project_begin(A&a,const cp::Input&x){const auto&f=x.f;constexpr std::array<U,16>owner{1,1,1,1,2,1,2,1,1,1,2,2,2,2,1,2},off{0x6e8,0x6ec,0x6f0,0x6f4,0xb,0x37a,0x589,0x93f1,0x6fa,0x6fc,0x1f8,0x6a8,0x6a9,0xe8,0x6c0,1},width{4,4,4,4,1,1,1,1,1,1,4,1,1,4,1,1};const std::array<U,16>v{*f.pbw.field6e8_bits,*f.pbw.field6ec_bits,*f.pbw.field6f0_bits,*f.pbw.field6f4_bits,*f.pw.field0b,*f.pbw.field37a,*f.pw.field589,*f.pbw.field93f1,x.p.selection_pbw.field6fa,*f.pbw.field6fc,*f.pw.field1f8,*f.pw.field6a8,*f.pw.field6a9,x.p.pw.fielde8,*f.pbw.field6c0,*f.pw.field01};for(U i=0;i<16;++i)write(a[owner[i]],off[i],width[i],v[i]);}
void compare_lookup(const wl::Output&out,U selected,U returned,U n,const Bytes&stack){need(out.returned==returned&&out.visited==n&&out.match.has_value()==(selected!=0),"lookup result differs from ARM");if(out.match){const auto&m=*out.match;need(selected==addresses[9]+m.index*256,"selected record identity");need(m.status==returned,"match status");for(U i=0;i<4;++i)need(m.vector34[i]==read(stack,16+4*i),"lookup stack vector");for(U i=0;i<3;++i)need(m.words40[i]==read(stack,32+4*i),"lookup stack words");need(m.field28&&std::holds_alternative<U>(*m.field28)&&std::get<U>(*m.field28)==read(stack,12),"lookup stack field28");}}
void rejection(Setup x,U which,px::Phase phase){x.context.world.manager=&x.manager;if(which==0)x.context.filter.object21.reset();if(which==1)x.context.delta_bits.reset();if(which==2)x.input.f.pbw.field54_bits.reset();if(which==3)x.input.f.pbw.field10_bits.reset();if(which==4)x.input.p.selection_pbw.field9.reset();if(which==5)x.input.f.pw.field1f8.reset();if(which==6)x.context.world.manager=nullptr;if(which==7)x.context.world.area_mask14.reset();if(which==8)x.manager.records[0].field28.reset();if(which==9)x.manager.records[0].next=wl::Index{0};if(which==10)x.context.delta_bits=0x7f800000;if(which==11)x.input.f.pbw.field54_bits=0x7f7fffff,x.context.delta_bits=0x7f7fffff;
 const auto before=x.input;const auto manager=x.manager;const auto ctx=context_value(x.context);auto r=px::apply(x.input.p,x.input.f,x.context);need(std::holds_alternative<px::Error>(r),"late unknown accepted");need(std::get<px::Error>(r).phase==phase,"wrong rejection phase");need(std::get<px::Error>(r).cause.index()==std::size_t(phase),"typed cause lost");need(x.input.p==before.p&&x.input.f==before.f&&x.manager==manager&&context_value(x.context)==ctx,"rejection mutated borrowed input");++typed;}
