 for(U i=0;i<11;++i){auto b=q.take(sizes[i]);x.arenas[i]={b.begin(),b.end()};}std::array<A,4> phases{};A source_previous=primary(x);
 for(U stage=0;stage<4;++stage){for(U i=0;i<3;++i){auto b=q.take(sizes[i]);phases[stage][i]={b.begin(),b.end()};}auto replay=source_previous;const auto ns=q.word();need(ns<=256,"store count");for(U i=0;i<ns;++i){const auto pc=q.word(),owner=q.word(),off=q.word(),n=q.word(),v=q.word();need(owner<3&&(n==1||n==2||n==4),"store shape");need(stage==0?(pc>=0x100000&&pc<0xd10000):stage==1?(pc>=0xb09ccc&&pc<0xb09d00):stage==2?(pc>=0xb3b3a0&&pc<0xb3b450):((pc>=0x5b8f14&&pc<0x5b8f80)||pc==0xb14100),"store phase PC");write(replay[owner],off,n,v);++stores;store_bytes+=n;}need(replay==phases[stage],"observed stores inconsistent");source_previous=phases[stage];}
 std::array<U,5> f{};for(auto&v:f){v=q.word();need(v<=1,"effect flag");}const fi::Effects effects{f[0]!=0,f[1]!=0,f[2]!=0,f[3]!=0,f[4]!=0};const auto selected=q.word(),returned=q.word(),nvisited=q.word(),count=q.word();need(nvisited<=128,"visits limit");auto sb=q.take(96);Bytes stack(sb.begin(),sb.end());q.word();auto calls=q.word();need(calls<=64,"call count");bool filter_called=false;U outer=0xffffffff,wrapper_return=0xffffffff,leaf_return=0xffffffff;for(U i=0;i<calls;++i){auto pc=q.word(),ret=q.word(),value=q.word();need(pc>=0x100000&&pc<0xd10000&&ret>=0x100000&&ret<0xd10000,"call identity");for(U j=0;j<4;++j)q.word();if(pc==0xd04924&&outer==0xffffffff)outer=value;if(pc==0xb33638)filter_called=true;if(pc==0x5b8f14)wrapper_return=value;if(pc==0x5ba61c)leaf_return=value;}need(filter_called==(f[0]!=0)&&outer==f[0]&&wrapper_return==returned&&leaf_return==selected,"call effects inconsistent");q.end();setup(x,count);
